 selected=rows[:n];pairs=sum(int(x['read_count']) for x in selected);tb=sum(sum(map(int,x['fastq_bytes'].split(';'))) for x in selected)/1e12
 # Separate measured CPU-equivalent floors from assumptions about unmeasured end-to-end work.
